import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.D1JEzK2q.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}'),o={name:"guide/troubleshooting.md"};function n(i,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Start with the smallest failing boundary: process, API, agent, provider, then channel delivery.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lines</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th><th>Verification after the fix</th></tr></thead><tbody><tr><td>Nothing listens</td><td>Owning service, bind address, port, startup log</td><td><code>/health</code> answers on the intended address</td></tr><tr><td>Health works, agent fails</td><td>Workspace exists, <code>AGENTS.md</code>, Claude authentication and executable</td><td>Agent answers a short direct request</td></tr><tr><td>Telegram bot stays silent</td><td>Pairing, allowed user, duplicate poller</td><td>Paired private chat receives a reply</td></tr><tr><td>Telegram group stays silent</td><td>Privacy Mode/admin status, group allowlist, mention gate</td><td>Mention produces a reply in the approved group</td></tr><tr><td>Discord receives empty messages</td><td>Message Content Intent and channel permissions</td><td>Bot receives text and answers</td></tr><tr><td>LINE webhook rejected</td><td>Signature and unchanged raw request body</td><td>A new signed webhook is accepted</td></tr><tr><td>MCP tools unavailable</td><td>Bun, MCP dependencies, generated session MCP config</td><td>A read-only tool returns a real result</td></tr><tr><td>API rejects a key</td><td>Key value, agent scope, write/admin requirement</td><td>The same request succeeds with appropriate scope</td></tr><tr><td>Personality unchanged</td><td>Source workspace files, generated <code>CLAUDE.md</code></td><td>New turn reflects the edited instructions</td></tr><tr><td>Heartbeat did not send</td><td>YAML, five-field cron, timezone, rate limit, <code>HEARTBEAT_OK</code></td><td>Run evidence and intended channel delivery</td></tr></tbody></table><h2 id="local-commands-work-public-url-fails" tabindex="-1">Local commands work, public URL fails <a class="header-anchor" href="#local-commands-work-public-url-fails" aria-label="Permalink to &quot;Local commands work, public URL fails&quot;">​</a></h2><p>A proxy may enforce separate authentication. Compare the address reported by <code>doctor</code> with the intended destination. Local CLI commands normally prefer the running gateway&#39;s local address; setting <code>--url</code> deliberately tests another address. <code>gateway.publicUrl</code> must point to this gateway&#39;s externally reachable origin for features that generate public links.</p><h2 id="context-looks-missing" tabindex="-1">Context looks missing <a class="header-anchor" href="#context-looks-missing" aria-label="Permalink to &quot;Context looks missing&quot;">​</a></h2><p>Check that you selected the intended agent, chat, and session. Session persistence and permanent chat history are distinct stores. A missing session file starts a fresh context; do not delete history or configuration as a diagnostic shortcut. See <a href="./agents.html">agents and sessions</a> and <a href="./memory.html">memory</a>.</p><h2 id="collect-a-useful-report" tabindex="-1">Collect a useful report <a class="header-anchor" href="#collect-a-useful-report" aria-label="Permalink to &quot;Collect a useful report&quot;">​</a></h2><p><code>claude-gateway debug-bundle</code> writes a small redacted diagnostics bundle. Review it before sharing, and include the installed version, failing command or action, expected behavior, actual result, and relevant timestamps. Remove credentials, private messages, and identifying data from manually copied logs.</p><p>For <code>ORCHESTRATION_DISABLED</code> or <code>PROFILE_INVENTORY_MISMATCH</code>, inspect the gateway mode and runtime profile using the <a href="./orchestration.html">orchestration guide</a>.</p><h2 id="memory-search-returns-nothing-or-an-old-fact" tabindex="-1">Memory search returns nothing or an old fact <a class="header-anchor" href="#memory-search-returns-nothing-or-an-old-fact" aria-label="Permalink to &quot;Memory search returns nothing or an old fact&quot;">​</a></h2><p>Confirm the search corpus and shared project first. Personal archive sources are <code>MEMORY.md</code>, <code>USER.md</code>, and Markdown under <code>memory/</code>; another workspace document is not automatically indexed. Read the source file to distinguish a missing fact from a stale index. A generated core index is a context optimization and does not mean the full source was erased.</p><p>If a note used to be searchable, inspect dreaming and staleness records and whether the source moved or disappeared. For durable archival notes that must survive aging, use the documented <code>memory/pinned/</code> location. Verify the result by retrieving an exact source excerpt in a new session.</p><h2 id="a-learned-skill-is-missing-or-unexpectedly-unchanged" tabindex="-1">A learned skill is missing or unexpectedly unchanged <a class="header-anchor" href="#a-learned-skill-is-missing-or-unexpectedly-unchanged" aria-label="Permalink to &quot;A learned skill is missing or unexpectedly unchanged&quot;">​</a></h2><p>Inspect <code>skills/.pending/</code> when learning runs in propose mode. In auto mode, inspect <code>SKILLS_LEARNED.md</code> and the live <code>SKILL.md</code>. Reaching the tool-call threshold only qualifies a session for review; the daily budget, reviewer outcome, duplicate checks, and provenance guard still apply. A human-authored same-name skill is deliberately protected from automatic overwrite.</p><p>For shared skills, edit <code>~/.claude-gateway/shared-skills/</code>, then verify the managed personal copy and generated menu. Editing only a <code>.shared</code>-marked copy in <code>~/.claude/skills/</code> can be undone on the next synchronization.</p><h2 id="an-app-is-installed-but-its-url-fails" tabindex="-1">An app is installed but its URL fails <a class="header-anchor" href="#an-app-is-installed-but-its-url-fails" aria-label="Permalink to &quot;An app is installed but its URL fails&quot;">​</a></h2><p>Read the installation job&#39;s terminal state and logs, then inspect the app&#39;s declared port name. The proxy path uses the manifest&#39;s name, not an arbitrary container port number. Check whether the app is still <code>restoring</code> or reports a boot <code>restoreError</code>. Rebuilds on a fresh Docker host may need longer than a simple restart.</p><p>If the app has an agent, check its workspace link, generated agent container, mounted binary paths, and staged Claude configuration. A host login change can refresh the seed without refreshing an already running container&#39;s copied configuration. Follow the <a href="./apps.html">app lifecycle and backup guide</a> before reinstalling or restoring data.</p><h2 id="a-schedule-fires-at-the-wrong-time-or-after-restart" tabindex="-1">A schedule fires at the wrong time or after restart <a class="header-anchor" href="#a-schedule-fires-at-the-wrong-time-or-after-restart" aria-label="Permalink to &quot;A schedule fires at the wrong time or after restart&quot;">​</a></h2><p>Heartbeats use the process timezone and convert interval shorthand into wall-clock cron. Managed cron jobs default to UTC unless their own timezone is set. Compare the actual schedule type and timezone rather than applying one scheduler&#39;s rules to the other.</p><p>Managed recurring jobs can catch up missed work after startup; this is capped and does not replay every missed tick. Inspect the prior run timestamp and current run log before manually triggering the job. A missing heartbeat message may instead be a normal rate-limited or <code>HEARTBEAT_OK</code> result.</p><p>Source modules for these checks: <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/agent/knowledge/indexer.ts" target="_blank" rel="noreferrer">knowledge indexing</a>, <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/agent/skill-learning/writer.ts" target="_blank" rel="noreferrer">skill writer</a>, <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/apps/installer.ts" target="_blank" rel="noreferrer">app installer</a>, and <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/cron/manager.ts" target="_blank" rel="noreferrer">cron manager</a>.</p><h2 id="a-task-is-queued-blocked-or-failed" tabindex="-1">A task is queued, blocked, or failed <a class="header-anchor" href="#a-task-is-queued-blocked-or-failed" aria-label="Permalink to &quot;A task is queued, blocked, or failed&quot;">​</a></h2><p>Read the persisted task state before retrying. <code>queued</code> means execution has not started; a progress acknowledgement does not change that. Check per-conversation/per-agent task limits, gateway process capacity, predecessor state, and workspace availability. An <code>after_success</code> continuation whose predecessor failed reports <code>TASK_DEPENDENCY_FAILED</code>; authorized recovery can use an <code>after_terminal</code> continuation with instructions to inspect the existing state first.</p><table tabindex="0"><thead><tr><th>Error</th><th>Meaning</th><th>Targeted check</th></tr></thead><tbody><tr><td><code>ORCHESTRATION_DISABLED</code></td><td>The task path is not enabled</td><td>Gateway-wide orchestration switch</td></tr><tr><td><code>PROFILE_FLAGS_CONFLICT</code></td><td>Custom Claude flags conflict with a managed profile</td><td>Remove conflicting <code>claude.extraFlags</code>; use supported settings</td></tr><tr><td><code>CLI_SKILL_UNAVAILABLE</code></td><td>Native skill absent from this worker runtime</td><td>Actual host/container skill inventory</td></tr><tr><td><code>WORKER_GIT_PROJECT_REQUIRED</code></td><td>Explicit worktree policy requires a Git project</td><td>Selected workspace mode and project root</td></tr><tr><td><code>SHARED_PROJECT_MUST_DIFFER_FROM_IDENTITY_WORKSPACE</code></td><td>Shared-lock project overlaps identity workspace</td><td>Use a separate project directory</td></tr><tr><td><code>CONTAINER_ISOLATION_REQUIRED</code></td><td>App container fails admission</td><td>Runtime privileges, namespaces, capabilities, and mounts</td></tr><tr><td><code>ARTIFACT_PATH_DENIED</code></td><td>Requested file is outside the permitted artifact scope</td><td>Original file location and active task/session ownership</td></tr></tbody></table><p>After interruption, inspect current files, remote side effects, and recorded test evidence before retrying the action. A timeout does not establish that edits disappeared or that a deploy failed. Likewise <code>cancel_requested</code> means stopping has been requested; report cancellation only after the terminal cancelled state is confirmed. Stopping a spoken response or chat decision does not cancel ongoing execution tasks.</p><p>Source: <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/session/runtime-profile.ts" target="_blank" rel="noreferrer">runtime profile rules</a>, <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/orchestration/tasks/driver.ts" target="_blank" rel="noreferrer">worker driver</a>, and <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/orchestration/task-controls.ts" target="_blank" rel="noreferrer">task controls</a>.</p>`,29)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
